"""SQLite access: connection setup, default location and numbered .sql migrations (DEC-0003)."""

import hashlib
import os
import re
import sqlite3
import subprocess
from collections.abc import Iterator
from contextlib import contextmanager
from datetime import UTC, datetime
from importlib.resources import files
from pathlib import Path

MIGRATIONS_DIR = files("harness") / "migrations"
_MIGRATION_NAME = re.compile(r"^(\d{4})_[a-z0-9_]+\.sql$")


def utcnow() -> str:
    return datetime.now(UTC).isoformat(timespec="seconds")


def git_env() -> dict[str, str]:
    """Environment for read-only git calls: never take optional locks or refresh the index."""
    return {**os.environ, "GIT_OPTIONAL_LOCKS": "0"}


def repo_root(cwd: Path | None = None) -> Path:
    """Git top-level of cwd (default: the current directory), or cwd itself outside git."""
    cwd = Path.cwd() if cwd is None else Path(cwd)
    try:
        result = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            cwd=cwd,
            env=git_env(),
            capture_output=True,
            text=True,
            check=False,
        )
    except OSError:
        return cwd.resolve()
    top = result.stdout.strip()
    return Path(top).resolve() if result.returncode == 0 and top else cwd.resolve()


def default_db_path(root: Path | None = None) -> Path:
    """Per-repository state DB under $HARNESS_HOME, outside the target repo. Creates nothing."""
    root = (root or repo_root()).resolve()
    digest = hashlib.sha256(str(root).encode()).hexdigest()[:16]
    return _projects_dir() / digest / "state.db"


def _projects_dir() -> Path:
    home = os.environ.get("HARNESS_HOME")
    base = Path(home) if home else Path.home() / ".local" / "share" / "harness"
    return base / "projects"


def _restrict(path: Path, created_dir: bool) -> None:
    """POSIX owner-only access; a pre-existing directory outside the harness home is left alone."""
    if os.name != "posix":
        return
    if created_dir or path.parent.resolve().is_relative_to(_projects_dir().resolve()):
        os.chmod(path.parent, 0o700)
    os.chmod(path, 0o600)


@contextmanager
def transaction(conn: sqlite3.Connection) -> Iterator[sqlite3.Connection]:
    """BEGIN IMMEDIATE ... COMMIT, rolling back on any exception."""
    conn.execute("BEGIN IMMEDIATE")
    try:
        yield conn
    except BaseException:
        conn.execute("ROLLBACK")
        raise
    conn.execute("COMMIT")


def _migrations() -> list[tuple[int, str, str]]:
    found = []
    for entry in MIGRATIONS_DIR.iterdir():
        match = _MIGRATION_NAME.match(entry.name)
        if match:
            found.append((int(match.group(1)), entry.name, entry.read_text(encoding="utf-8")))
    found.sort()
    versions = [version for version, _, _ in found]
    if len(versions) != len(set(versions)):
        raise RuntimeError(f"duplicate migration versions in {MIGRATIONS_DIR}")
    return found


def apply_migrations(conn: sqlite3.Connection) -> list[str]:
    """Apply pending migrations, each atomically with its schema_migrations row."""
    conn.execute(
        "CREATE TABLE IF NOT EXISTS schema_migrations "
        "(version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at TEXT NOT NULL)"
    )
    applied = []
    for version, name, sql in _migrations():
        conn.execute("BEGIN IMMEDIATE")
        try:
            done = conn.execute(
                "SELECT 1 FROM schema_migrations WHERE version = ?", (version,)
            ).fetchone()
            if not done:
                conn.executescript(sql)
                conn.execute(
                    "INSERT INTO schema_migrations (version, name, applied_at) VALUES (?, ?, ?)",
                    (version, name, utcnow()),
                )
                applied.append(name)
        except BaseException:
            if conn.in_transaction:
                conn.execute("ROLLBACK")
            raise
        conn.execute("COMMIT")
    return applied


def connect(path: Path) -> sqlite3.Connection:
    path = Path(path)
    created_dir = not path.parent.exists()
    path.parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(path, autocommit=True)
    try:
        _restrict(path, created_dir)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA busy_timeout=5000")
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA foreign_keys=ON")
        apply_migrations(conn)
    except BaseException:
        conn.close()
        raise
    return conn

harness/knowledge/extract.py:
"""Deterministic observations from safe bytes; never import or execute indexed code."""

import ast
import re
from pathlib import PurePosixPath

from harness.knowledge.models import Assertion, Extraction, SourceVersion
from harness.md_record import scan_record


def extract_source(source: SourceVersion) -> Extraction:
    raw, locator = source.raw, source.locator
    text = raw.decode("utf-8")
    module = ".".join(PurePosixPath(locator).with_suffix("").parts)
    if module.endswith(".__init__"):
        module = module[:-9]
    subject = f"module:{module}" if source.kind == "python" else f"file:{locator}"
    assertions = [
        Assertion(
            subject,
            "described-by",
            None,
            locator,
            text[:8192],
            0,
            min(len(raw), len(text[:8192].encode())),
        )
    ]
    coverage = []
    if source.kind == "python":
        try:
            tree = ast.parse(text)
        except SyntaxError:
            return Extraction(tuple(assertions), ({"locator": locator, "status": "syntax-error"},))
        lines = raw.splitlines(keepends=True)
        offsets = [0]
        for line in lines:
            offsets.append(offsets[-1] + len(line))
        qualified = {}

        def definitions(node, prefix=""):
            for child in ast.iter_child_nodes(node):
                name = prefix
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                    name = f"{prefix}.{child.name}" if prefix else child.name
                    qualified[id(child)] = name
                definitions(child, name)

        definitions(tree)
        for node in ast.walk(tree):
            if isinstance(
                node,
                (ast.Import, ast.ImportFrom, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef),
            ):
                start, end = offsets[node.lineno - 1], offsets[node.end_lineno]
                fragment = raw[start:end].decode()
                if isinstance(node, ast.Import):
                    targets = [alias.name for alias in node.names]
                elif isinstance(node, ast.ImportFrom):
                    base = (
                        module.split(".")
                        if locator.endswith("/__init__.py")
                        else module.split(".")[:-1]
                    )
                    if node.level:
                        base = (
                            base[: len(base) - node.level + 1]
                            if node.level <= len(base) + 1
                            else []
                        )
                        target = ".".join([*base, *([node.module] if node.module else [])])
                    else:
                        target = node.module or ""
                    targets = [target] if target else []
                    if not node.module:
                        targets = [
                            ".".join(filter(None, [target, alias.name])) for alias in node.names
                        ]
                else:
                    assertions.append(
                        Assertion(
                            subject,
                            "defines",
                            f"symbol:{module}:{qualified[id(node)]}",
                            None,
                            fragment[:1024],
                            start,
                            end,
                            origin="static-analysis",
                        )
                    )
                    continue
                for target in targets:
                    assertions.append(
                        Assertion(
                            subject,
                            "imports",
                            f"module:{target}",
                            None,
                            fragment,
                            start,
                            end,
                            origin="static-analysis",
                        )
                    )
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id in ("__import__", "eval", "exec")
            ):
                coverage.append({"locator": locator, "status": "dynamic-reference-unresolved"})
    elif PurePosixPath(locator).name.startswith("DEC-") and locator.endswith(".md"):
        title, fields, sections = scan_record(text.splitlines())
        if fields.get("id") and fields.get("version") and sections.get("Decision"):
            decision = f"decision:{fields['id']}:v{fields['version']}"
            for predicate, value in [
                ("title", title),
                ("status", fields.get("status", "unknown")),
                ("scope", fields.get("scope", "")),
                ("rationale", sections.get("Rationale", "")),
                ("decision", sections["Decision"]),
            ]:
                assertions.append(
                    Assertion(
                        decision,
                        predicate,
                        None,
                        value,
                        str(value),
                        0,
                        len(raw),
                        applicability={"historical": "/history/" in locator},
                    )
                )
            for ref in re.findall(r"\bDEC-\d+\b", fields.get("supersedes", "")):
                assertions.append(
                    Assertion(
                        decision,
                        "supersedes",
                        f"decision:{ref}",
                        None,
                        fields["supersedes"],
                        0,
                        len(raw),
                    )
                )
        else:
            coverage.append({"locator": locator, "status": "malformed-decision"})
    elif not locator.endswith(".md"):
        coverage.append({"locator": locator, "status": "text-only-no-dependency-analysis"})
    # Explicit document references are observations, never semantic entailments.
    if locator.endswith(".md"):
        for match in re.finditer(r"\b(?:DEC-\d+|REQ-[A-Za-z0-9_-]+)\b", text):
            start = len(text[: match.start()].encode())
            end = start + len(match[0].encode())
            kind = "decision" if match[0].startswith("DEC-") else "requirement"
            assertions.append(
                Assertion(subject, "references", f"{kind}:{match[0]}", None, match[0], start, end)
            )
    return Extraction(tuple(assertions), tuple(coverage))

harness/knowledge/models.py:
"""Immutable public knowledge contracts. These describe context, never execution authority."""

import hashlib
import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

EXTRACTOR_VERSION = "1"
MAX_SOURCE_BYTES = 1_048_576
MAX_REFRESH_BYTES = 67_108_864


def canonical(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def digest(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def identity(*parts: str) -> str:
    return digest(canonical(parts).encode())


@dataclass(frozen=True)
class KnowledgeScope:
    project_id: str
    repository: Path
    principal_id: str
    purpose: str = "operator"
    task_id: str | None = None
    execution_id: str | None = None
    epoch_id: str | None = None
    authority_generation: int = 0
    policy_generation: int = 0
    role: str = "operator"
    permitted_source_versions: frozenset[str] | None = None
    packet_hash: str | None = None


@dataclass(frozen=True)
class RefreshRequest:
    max_files: int = 10000
    max_file_bytes: int = MAX_SOURCE_BYTES
    included_paths: tuple[str, ...] = ()


@dataclass(frozen=True)
class SourceVersion:
    source_id: str
    version_id: str
    locator: str
    kind: str
    content_sha256: str
    raw: bytes
    observation: dict


@dataclass(frozen=True)
class SourceInventory:
    sources: tuple[SourceVersion, ...]
    complete: bool
    coverage: tuple[dict, ...]
    observation: dict


@dataclass(frozen=True)
class Assertion:
    subject: str
    predicate: str
    object: str | None
    value: Any
    text: str
    start_byte: int
    end_byte: int
    origin: str = "structured"
    verification: str = "source-backed"
    confidence: float = 1.0
    applicability: dict = field(default_factory=dict)


@dataclass(frozen=True)
class Extraction:
    assertions: tuple[Assertion, ...]
    coverage: tuple[dict, ...] = ()


@dataclass(frozen=True)
class PreparedSnapshot:
    scope: KnowledgeScope
    inventory: SourceInventory
    extractions: tuple[Extraction, ...]
    expected_policy_generation: int


@dataclass(frozen=True)
class RefreshResult:
    snapshot_id: str | None
    status: str
    coverage: tuple[dict, ...]


@dataclass(frozen=True)
class QueryLimits:
    bytes: int = 32768
    assertions: int = 40
    hops: int = 2
    examined_edges: int = 200

    def validate(self) -> None:
        if not (
            1024 <= self.bytes <= 32768
            and 1 <= self.assertions <= 40
            and 0 <= self.hops <= 2
            and 0 <= self.examined_edges <= 200
        ):
            raise ValueError("knowledge limits exceed supported bounds")


@dataclass(frozen=True)
class ContextRequest:
    query: str = ""
    entity_refs: tuple[str, ...] = ()
    as_of_snapshot: str | None = None
    limits: QueryLimits = field(default_factory=QueryLimits)


@dataclass(frozen=True)
class ContextBundle:
    bundle_hash: str
    payload: dict

    def to_dict(self) -> dict:
        return {"bundle_hash": self.bundle_hash, **self.payload}

harness/knowledge/policy.py:
"""Scope validation before any graph selection, counts, ranking or cached reads."""

from dataclasses import asdict

from harness.knowledge.models import KnowledgeScope, canonical, digest, identity

_PURPOSES = {"operator", "investigation", "implementation", "fresh-review", "comparison-review"}


def operator_scope(repository, *, task_id=None, purpose="operator"):
    root = repository.resolve()
    return KnowledgeScope(identity(str(root)), root, "local-operator", purpose, task_id=task_id)


def validate_scope(conn, scope):
    if scope.purpose not in _PURPOSES or not scope.principal_id:
        raise PermissionError("unissued knowledge purpose")
    if scope.purpose in {"fresh-review", "comparison-review"} and (
        not scope.packet_hash or scope.permitted_source_versions is None
    ):
        raise PermissionError("review requires an explicit packet-local source binding")
    project = conn.execute(
        "SELECT * FROM knowledge_projects WHERE project_id=?", (scope.project_id,)
    ).fetchone()
    if not project or project["repository_identity"] != str(scope.repository.resolve()):
        raise PermissionError("knowledge project mismatch")
    if project["policy_generation"] != scope.policy_generation:
        raise PermissionError("knowledge policy revoked or stale")
    if scope.execution_id:
        execution = conn.execute(
            "SELECT * FROM executions WHERE id=?", (scope.execution_id,)
        ).fetchone()
        if not execution or (
            execution["task_id"],
            execution["epoch_id"],
            execution["authority_generation"],
        ) != (scope.task_id, scope.epoch_id, scope.authority_generation):
            raise PermissionError("knowledge execution scope is stale")
    return project


def policy_digest(scope):
    data = asdict(scope)
    data["repository"] = str(scope.repository.resolve())
    allowed = scope.permitted_source_versions
    data["permitted_source_versions"] = sorted(allowed) if allowed is not None else None
    return digest(canonical(data).encode())


def derive_scope(controller, execution, principal, state, repository):
    """Called only after OperationController's live-principal/authority admission.

    Review roles remain closed until the supervisor issues packet-local source bindings.
    They cannot elect their own purpose or allowlist through tool arguments.
    """
    if principal["role"] != "orchestrator" and not principal.get("writable"):
        raise PermissionError("packet-local knowledge binding required for read-only agent")
    root = repository.resolve()
    project_id = identity(str(root))
    project = controller.conn.execute(
        "SELECT policy_generation FROM knowledge_projects WHERE project_id=?", (project_id,)
    ).fetchone()
    if not project:
        raise ValueError("knowledge not indexed; run native investigation first")
    return KnowledgeScope(
        project_id,
        root,
        principal["thread_id"],
        "implementation",
        task_id=execution["task_id"],
        execution_id=execution["id"],
        epoch_id=execution["epoch_id"],
        authority_generation=execution["authority_generation"],
        policy_generation=project["policy_generation"],
        role=principal["role"],
    )

harness/knowledge/query.py:
"""Partition-first lexical/graph retrieval with complete citations and serialized budgets."""

import json
import re
from collections import deque

from harness.db import transaction, utcnow
from harness.knowledge.models import (
    MAX_SOURCE_BYTES,
    ContextBundle,
    ContextRequest,
    canonical,
    digest,
)
from harness.knowledge.policy import policy_digest, validate_scope
from harness.knowledge.sources import read_source

_DEFAULT_CONTEXT_REQUEST = ContextRequest()


def _partition(conn, scope, snapshot):
    versions = {
        r[0]
        for r in conn.execute(
            "SELECT version_id FROM knowledge_snapshot_sources WHERE snapshot_id=? "
            "AND membership_state='present'",
            (snapshot,),
        )
    }
    if scope.permitted_source_versions is not None:
        versions &= scope.permitted_source_versions
    if not versions:
        return {}, {}
    marks = ",".join("?" for _ in versions)
    candidates = conn.execute(
        "SELECT DISTINCT m.assertion_id FROM knowledge_snapshot_assertions m "
        "JOIN knowledge_evidence e ON e.assertion_id=m.assertion_id "
        f"WHERE m.snapshot_id=? AND e.version_id IN ({marks}) "
        "AND NOT EXISTS (SELECT 1 FROM knowledge_evidence denied "
        f"WHERE denied.assertion_id=m.assertion_id AND denied.version_id NOT IN ({marks}))",
        (snapshot, *sorted(versions), *sorted(versions)),
    ).fetchall()
    evidence, eligible = {}, {}
    for candidate in candidates:
        aid = candidate[0]
        row = conn.execute(
            "SELECT a.*, s.scoped_key AS subject, o.scoped_key AS object "
            "FROM knowledge_assertions a JOIN knowledge_entities s ON s.entity_id=a.subject_id "
            "LEFT JOIN knowledge_entities o ON o.entity_id=a.object_id "
            "WHERE a.assertion_id=? AND a.project_id=?",
            (aid, scope.project_id),
        ).fetchone()
        if row is None:
            continue
        refs = [
            dict(r)
            for r in conn.execute(
                "SELECT e.*, v.content_sha256, s.locator FROM knowledge_evidence e "
                "JOIN knowledge_source_versions v ON v.version_id=e.version_id "
                "JOIN knowledge_sources s ON s.source_id=v.source_id WHERE e.assertion_id=?",
                (aid,),
            )
        ]
        evidence[aid], eligible[aid] = refs, dict(row)
    # Reject incomplete/cyclic transitive provenance before matching or counting.
    parents = {
        aid: [
            r[0]
            for r in conn.execute(
                "SELECT parent_assertion_id FROM knowledge_derivations WHERE assertion_id=?", (aid,)
            )
        ]
        for aid in eligible
    }

    def allowed(aid, visiting):
        return (
            aid in eligible
            and aid not in visiting
            and all(allowed(parent, visiting | {aid}) for parent in parents[aid])
        )

    eligible = {aid: row for aid, row in eligible.items() if allowed(aid, set())}
    return eligible, evidence


def _citation_current(scope, ref):
    try:
        raw = read_source(scope.repository, ref["locator"], MAX_SOURCE_BYTES)
        return (
            digest(raw) == ref["content_sha256"]
            and digest(raw[ref["start_byte"] : ref["end_byte"]]) == ref["span_sha256"]
        )
    except (OSError, UnicodeError, ValueError):
        return False


def query(conn, scope, request: ContextRequest = _DEFAULT_CONTEXT_REQUEST) -> ContextBundle:
    request.limits.validate()
    if len(request.query.encode()) > 4096 or len(request.entity_refs) > 40:
        raise ValueError("knowledge request too large")
    project = validate_scope(conn, scope)
    snapshot = request.as_of_snapshot or project["active_snapshot_id"]
    snap = conn.execute(
        "SELECT * FROM knowledge_snapshots WHERE snapshot_id=? AND project_id=?",
        (snapshot, scope.project_id),
    ).fetchone()
    if not snap:
        raise ValueError("no authorized knowledge snapshot; refresh first")
    eligible, evidence = _partition(conn, scope, snapshot)
    tokens = set(re.findall(r"[\w.-]+", request.query.lower()))
    scored = []
    for aid, row in eligible.items():
        haystack = f"{row['subject']} {row['object'] or ''} {row['text']}".lower()
        score = sum(token in haystack for token in tokens)
        explicit = row["subject"] in request.entity_refs or row["object"] in request.entity_refs
        if explicit or score:
            scored.append((-int(explicit), -score, aid))
    scored.sort()
    seeds = [aid for _, _, aid in scored[: request.limits.assertions]]
    selected, paths, examined = list(seeds), {}, 0
    queue = deque((aid, 0, [aid]) for aid in seeds)
    while queue and examined < request.limits.examined_edges:
        aid, depth, path = queue.popleft()
        if depth >= request.limits.hops:
            continue
        row = eligible[aid]
        entities = {row["subject"], row["object"]} - {None}
        for other, edge in sorted(eligible.items()):
            if edge["predicate"] not in {"imports", "defines", "references", "supersedes"}:
                continue
            if not entities.intersection({edge["subject"], edge["object"]}):
                continue
            if examined >= request.limits.examined_edges:
                break
            examined += 1
            if other not in selected:
                selected.append(other)
                paths[other] = [*path, other]
                queue.append((other, depth + 1, paths[other]))
    ordered, visited = [], set()

    def include_parents(aid):
        if aid in visited:
            return
        visited.add(aid)
        for parent in conn.execute(
            "SELECT parent_assertion_id FROM knowledge_derivations WHERE assertion_id=?", (aid,)
        ):
            include_parents(parent[0])
        ordered.append(aid)

    for aid in selected:
        include_parents(aid)
    selected = ordered
    historical = snapshot != project["active_snapshot_id"]
    payload = {
        "schema_version": 1,
        "snapshot_id": snapshot,
        "policy_digest": policy_digest(scope),
        "purpose": scope.purpose,
        "query": request.query,
        "assertions": [],
        "citations": [],
        "paths": [],
        "ambiguities": [],
        "conflicts": [],
        "staleness": [],
        "coverage": json.loads(snap["coverage_json"]),
        "budget": {
            "max_bytes": request.limits.bytes,
            "max_assertions": request.limits.assertions,
            "max_hops": request.limits.hops,
            "max_examined_edges": request.limits.examined_edges,
            "examined_edges": examined,
            "serialized_bytes": 0,
        },
        "truncation": False,
        "notice": "Context grants no execution or approval authority; "
        "no result proves no dependency.",
    }
    # Coverage is project-wide metadata and cannot enter packet-restricted retrieval.
    if scope.permitted_source_versions is not None:
        payload["coverage"] = [
            {"status": "packet-local", "whole_repository_coverage": "not-assessed"}
        ]
    for aid in selected:
        if len(payload["assertions"]) >= request.limits.assertions:
            payload["truncation"] = True
            break
        parents = {
            r[0]
            for r in conn.execute(
                "SELECT parent_assertion_id FROM knowledge_derivations WHERE assertion_id=?", (aid,)
            )
        }
        if not parents <= {a["assertion_id"] for a in payload["assertions"]}:
            payload["truncation"] = True
            continue
        refs = evidence[aid]
        if not historical and not all(_citation_current(scope, ref) for ref in refs):
            payload["staleness"].append({"assertion_id": aid, "status": "withheld-stale-evidence"})
            continue
        row = eligible[aid]
        assertion = {
            k: row[k]
            for k in (
                "assertion_id",
                "subject",
                "predicate",
                "object",
                "text",
                "origin",
                "verification",
                "confidence",
            )
        }
        applicability = json.loads(row["applicability_json"])
        assertion.update(
            value=json.loads(row["value_json"]),
            historical=historical or bool(applicability.get("historical")),
            applicability=applicability,
        )
        citations = [
            {
                k: ref[k]
                for k in (
                    "assertion_id",
                    "version_id",
                    "locator",
                    "content_sha256",
                    "start_byte",
                    "end_byte",
                    "span_sha256",
                )
            }
            for ref in refs
        ]
        candidate = {
            **payload,
            "assertions": [*payload["assertions"], assertion],
            "citations": [*payload["citations"], *citations],
        }
        if aid in paths:
            packed = {item["assertion_id"] for item in candidate["assertions"]}
            if not set(paths[aid]) <= packed:
                continue
            candidate["paths"] = [*payload["paths"], paths[aid]]
        if len(canonical(candidate).encode()) + 128 > request.limits.bytes:
            payload["truncation"] = True
            continue
        payload = candidate
    # Only explicit single-valued predicates admit deterministic contradiction checks.
    groups = {}
    for assertion in payload["assertions"]:
        if assertion["predicate"] in {"status", "scope", "title"}:
            key = (
                assertion["subject"],
                assertion["predicate"],
                canonical(assertion["applicability"]),
            )
            groups.setdefault(key, []).append(assertion)
    for (subject, predicate, _), assertions in groups.items():
        if len({canonical(a["value"]) for a in assertions}) > 1:
            payload["conflicts"].append(
                {
                    "subject": subject,
                    "predicate": predicate,
                    "assertion_ids": [a["assertion_id"] for a in assertions],
                    "status": "incompatible-sourced-values",
                }
            )
    # Bound metadata as well as assertions. Never truncate evidence or a JSON value.
    if len(canonical(payload).encode()) + 128 > request.limits.bytes:
        payload["staleness"], payload["coverage"] = [], [{"status": "metadata-truncated"}]
        payload["conflicts"] = []
        payload["truncation"] = True
    while True:
        size = len(canonical({"bundle_hash": "0" * 64, **payload}).encode())
        if payload["budget"]["serialized_bytes"] == size:
            break
        payload["budget"]["serialized_bytes"] = size
    if size > request.limits.bytes:
        raise ValueError("request metadata exceeds bundle budget")
    validate_scope(conn, scope)
    # A last source read closes edits during selection; callers retry on a changed citation.
    if not historical and not all(_citation_current(scope, ref) for ref in payload["citations"]):
        raise ValueError("selected source changed before bundle publication")
    encoded = canonical(payload)
    bundle_hash = digest(encoded.encode())
    with transaction(conn):
        current = validate_scope(conn, scope)
        if not request.as_of_snapshot and current["active_snapshot_id"] != snapshot:
            raise ValueError("knowledge snapshot changed before bundle publication")
        conn.execute(
            "INSERT OR IGNORE INTO knowledge_bundles VALUES (?,?,?,?,?,?,?,NULL)",
            (
                bundle_hash,
                scope.project_id,
                snapshot,
                policy_digest(scope),
                scope.purpose,
                encoded,
                utcnow(),
            ),
        )
        for ref in payload["citations"]:
            conn.execute(
                "INSERT OR IGNORE INTO knowledge_bundle_sources VALUES (?,?)",
                (bundle_hash, ref["version_id"]),
            )
    return ContextBundle(bundle_hash, payload)


def explain(conn, scope, bundle_hash: str, assertion_id: str) -> dict:
    validate_scope(conn, scope)
    row = conn.execute(
        "SELECT * FROM knowledge_bundles WHERE bundle_hash=? AND project_id=?",
        (bundle_hash, scope.project_id),
    ).fetchone()
    if not row or row["invalidated_at"] or row["policy_digest"] != policy_digest(scope):
        raise PermissionError("bundle unavailable to current scope")
    payload = json.loads(row["payload"])
    assertions = [a for a in payload["assertions"] if a["assertion_id"] == assertion_id]
    if not assertions:
        raise ValueError("assertion absent from bundle")
    citations = [c for c in payload["citations"] if c["assertion_id"] == assertion_id]
    if not assertions[0]["historical"] and not all(_citation_current(scope, c) for c in citations):
        raise ValueError("bundle evidence is stale")
    return {
        "assertion": assertions[0],
        "citations": citations,
        "paths": [p for p in payload["paths"] if assertion_id in p],
        "authority": "derived context only",
    }

